        let d1 = Mutation::diff(&SemioVideoMutation::SetStreamMeta(set_stream_meta::SetStreamMeta { index: 1, kind: SemioVideoStreamKind::Video, codec: "patched".into(), width: 1, height: 1, rate: SemioRational { num: 2, den: 1 } }), &base);
